def new(land=False,tjb=False):
 d=Document();s=d.sections[0]
 s.page_width=Cm(29.7 if land else 21);s.page_height=Cm(21 if land else 29.7)
 s.top_margin=Cm(1.3 if land else 1.25 if tjb else 2);s.bottom_margin=Cm(1.3 if land else 1.0 if tjb else 2);s.left_margin=Cm(1.5 if land else 2.25 if tjb else 3);s.right_margin=Cm(1.5)
 for name in ['Normal','Title','Heading 1','Heading 2']:
  st=d.styles[name];st.font.name='Times New Roman';st.font.color.rgb=RGBColor(0,0,0);st.font.size=Pt(10.5 if land else 12)
  st.paragraph_format.space_after=Pt(3 if land else 5);st.paragraph_format.line_spacing=1.0 if land else 1.05
 d.styles['Title'].font.size=Pt(18 if land else 16);d.styles['Title'].font.bold=True
 for name in ['Heading 1','Heading 2']:d.styles[name].font.size=Pt(12 if land else 14);d.styles[name].font.bold=True
 return d
def p(d,text='',bold=False,code=False):
 x=d.add_paragraph();r=x.add_run(text);r.bold=bold
 if code:r.font.name='Courier New';r.font.size=Pt(10)
 return x
def title(d,t):
 x=d.add_paragraph(t,'Title');x.alignment=WD_ALIGN_PARAGRAPH.CENTER

def table(d,heads,rows,widths=None,header=True):
 t=d.add_table(rows=0,cols=len(heads));t.alignment=WD_TABLE_ALIGNMENT.CENTER;t.autofit=False
 if widths:
  for c,w in zip(t.columns,widths):c.width=Cm(w)
 for i,row in enumerate(([heads] if header else [])+rows):
  cells=t.add_row().cells
  for j,(c,txt) in enumerate(zip(cells,row)):
   if widths:c.width=Cm(widths[j])
   c.text=str(txt);c.vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
   pr=c._tc.get_or_add_tcPr();mar=OxmlElement('w:tcMar')
   for k,v in [('top',35),('bottom',35),('left',85),('right',85)]:
    el=OxmlElement('w:'+k);el.set(qn('w:w'),str(v));el.set(qn('w:type'),'dxa');mar.append(el)
   pr.append(mar)
   borders=OxmlElement('w:tcBorders')
   for side in ['top','left','bottom','right']:
    el=OxmlElement('w:'+side);el.set(qn('w:val'),'single');el.set(qn('w:sz'),'4');el.set(qn('w:color'),'B7B7B7');borders.append(el)
   pr.append(borders)
   for par in c.paragraphs:
    par.paragraph_format.space_after=Pt(1);par.paragraph_format.space_before=Pt(1)
    for r in par.runs:r.font.name='Times New Roman';r.font.size=Pt(10.5 if len(heads)>3 else 11)
   if header and i==0:
    sh=OxmlElement('w:shd');sh.set(qn('w:fill'),'EAF0F8');pr.append(sh)
    for r in c.paragraphs[0].runs:r.bold=True
  trpr=t.rows[-1]._tr.get_or_add_trPr();trpr.append(OxmlElement('w:cantSplit'))
  if header and i==0:trpr.append(OxmlElement('w:tblHeader'))
 return t
def link(d,label,url):
 x=d.add_paragraph();h=OxmlElement('w:hyperlink');h.set(qn('r:id'),x.part.relate_to(url,RT.HYPERLINK,is_external=True));r=OxmlElement('w:r');pr=OxmlElement('w:rPr');col=OxmlElement('w:color');col.set(qn('w:val'),'174EA6');pr.append(col);r.append(pr);txt=OxmlElement('w:t');txt.text=label;r.append(txt);h.append(r);x._p.append(h);return x
def lines(d,n=2):
 for _ in range(n):p(d,'________________________________________________________________________')
